function moduleSectionNav(items=[],scope=''){
  if(items.length<2)return'';
  const saved=scope?moduleSectionScopes[scope]:moduleSection;
  const active=items.some(([id])=>id===saved)?saved:items[0][0];
  return `<nav class="module-section-nav" aria-label="Sections" ${scope?`data-module-section-scope="${scope}"`:''}>${items.map(([id,label])=>`<button type="button" class="${active===id?'active':''}" data-module-section="${id}">${label}</button>`).join('')}</nav>`;
}
function applyModuleSections(root=document){
  const panes=[...root.querySelectorAll('[data-module-pane]')];
  root.querySelectorAll('.module-section-nav').forEach(nav=>{
    const scope=nav.dataset.moduleSectionScope||'';
    const sectionRoot=scope?nav.closest('[data-module-section-root]'):null;
    const sections=[...nav.querySelectorAll('[data-module-section]')].map(x=>x.dataset.moduleSection);
    const saved=scope?moduleSectionScopes[scope]:moduleSection;
    const active=sections.includes(saved)?saved:sections[0]||'';
    panes.filter(p=>scope
      ? p.closest('[data-module-section-root]')===sectionRoot
      : !p.closest('[data-module-section-root]')
    ).forEach(p=>p.hidden=p.dataset.modulePane!==active);
  });
}

function orders(){const total=(state.orders||[]).filter(x=>x.status==='paid').reduce((s,x)=>s+(+x.amount||0),0);return `<section>${head(t('orders'))}<div class="grid">${card(t('sales'),`<div class="kpi">${money(total)}</div>`)}${card(t('orders'),`<div class="kpi">${state.orders.length}</div>`)}</div>${card(t('newOrder'),`<form id="orderForm" class="form"><input name="reference" required placeholder="${t('orderReference')}"><input name="amount" required type="number" min="0" step=".01" placeholder="${t('amount')}"><select name="status"><option value="open">${t('open')}</option><option value="paid">${t('paid')}</option></select><button class="btn primary">${t('add')}</button></form>${rows(state.orders,(x,i)=>editingRow('orders',i)?`<form class="form inline-edit" data-edit-form="orders" data-index="${i}"><input name="reference" required value="${esc(x.reference)}"><input name="amount" required type="number" min="0" step=".01" value="${esc(x.amount)}"><select name="status"><option value="open" ${x.status==='open'?'selected':''}>${t('open')}</option><option value="paid" ${x.status==='paid'?'selected':''}>${t('paid')}</option></select>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.reference)}</strong><br><small class="muted">${t(x.status||'open')}</small></span><span class="row-actions"><strong>${money(x.amount)}</strong>${actions('orders',i)}</span></div>`,'noOrders')}`)}</section>`}
function operations(){const quick=['orders','stock','planning','recipes','reservations','customers','haccp','incidents'].filter(canPage),routine=dailyRoutineStatus(state),closing=closingControl(state),summary=`<div class="routine-summary"><span><strong>${routine.done}/${routine.total}</strong><small>${t('routineProgress')}</small></span><span><strong>${routine.opening.pending}</strong><small>${t('openingPending')}</small></span><span><strong>${routine.closing.pending}</strong><small>${t('closingPending')}</small></span>${closing.ready?`<span class="pill good">✓ ${t('closingReady')}</span>`:''}</div>`,closingCard=routine.closing.total?card(t('closingControl'),`<div class="payment-summary"><div class="payment-summary-row"><span>${t('closingPending')}</span><strong>${closing.closingPending}</strong></div><div class="payment-summary-row"><span>${t('openHaccpIssues')}</span><strong>${closing.haccpIssues}</strong></div><div class="payment-summary-row"><span>${t('openOrders')}</span><strong>${closing.openOrders}</strong></div></div><p class="muted">${closing.ready?t('closingReadyHint'):t('closingBlockedHint')}</p>${canPage('handover')?`<button class="btn compact" data-page="handover">${t('prepareHandover')}</button>`:''}`):'';return `<section class="artisan-page operations-artisan">${head(t('operations'))}<div class="artisan-hero artisan-hero-small"><div class="artisan-hero-mark">${icon('operations')}</div><div><span class="artisan-eyebrow">${t('today')}</span><h2>${t('dashboardSub')}</h2></div></div><div class="modules artisan-ops">${quick.map(k=>`<button class="module" data-page="${k}">${icon(k)}<strong>${t(k)}</strong></button>`).join('')}</div>${card(t('todayTasks'),`${summary}${state.tasks.map((x,i)=>`<label class="row artisan-check"><span>${t(x[0])}${x[2]?.type?`<small class="muted">${t(x[2].type)}</small>`:''}</span><input type="checkbox" data-task="${i}" ${x[1]?'checked':''}></label>`).join('')}`)}${closingCard}</section>`}
function haccp(){return `<section class="artisan-page module-screen">${head(t('haccp'))}${moduleSectionNav([['daily',t('temperatureReadings')],['cleaning',t('cleaning')],['audits',t('audits')]])}<div data-module-pane="daily">${card(t('temperatureReadings'),`<form id="tempForm" class="form"><input name="equipment" required placeholder="${t('equipment')}"><input name="value" required type="number" step=".1" placeholder="°C"><button class="btn primary">${t('add')}</button></form>${rows(state.temps,(x,i)=>editingRow('temps',i)?`<form class="form inline-edit" data-edit-form="temps" data-index="${i}"><input name="equipment" required value="${esc(x.equipment)}"><input name="value" required type="number" step=".1" value="${esc(x.value)}">${editButtons()}</form>`:`<div class="row"><span>${esc(x.equipment)}</span><span class="row-actions"><strong>${esc(x.value)} °C</strong>${actions('temps',i)}</span></div>` ,'noReadings')}`)}</div><div data-module-pane="cleaning">${card(t('cleaning'),`<p class="muted">${t('cleaning')}</p><button class="btn primary" data-page="cleaning">${t('cleaning')}</button>`)}</div><div data-module-pane="audits">${card(t('audits'),`<button class="btn primary" data-page="audits">${t('audits')}</button>`)}</div></section>`}
function finance(){
  const selectedDate=financeDate||today(),totals=financeDayTotals(state,selectedDate),series=revenueSeries(state,'day'),max=Math.max(1,...series.map(x=>x.revenue)),fmt=x=>new Intl.DateTimeFormat(language(),{weekday:'short'}).format(x.date),cockpit=profitLeakCockpit(state),benchmark=multiRestaurantBenchmark(state),monthStart=selectedDate.slice(0,8)+'01',profiles=accountingIntegrationProfiles();
  const leakRows=cockpit.signals.map(x=>`<div class="row"><span><strong>${t('profitLeak_'+x.code)}</strong><br><small class="muted">${x.count||0} · ${x.shareOfRevenue}% ${t('ofRevenue')}</small></span><span class="row-actions"><strong>${money(x.amount)}</strong><span class="pill ${x.severity==='urgent'?'bad':x.severity==='warning'?'warning':x.severity==='good'?'good':'info'}">${t('severity_'+x.severity)}</span></span></div>`).join('');
  const benchmarkRows=benchmark.rows.map(x=>`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${x.covers} ${t('covers')} · ${t('avgTicket')} ${money(x.avgTicket)} · ${t('foodCost')} ${x.foodCost}%</small></span><span class="row-actions"><strong>${money(x.revenue)}</strong><small>${t('result')}: ${money(x.result)} · ${x.revenueVsNetwork>0?'+':''}${x.revenueVsNetwork}% ${t('vsNetwork')}</small></span></div>`).join('');
  const exportButtons=['sales','vat','payments','refunds','purchases'].map(kind=>`<button type="button" class="btn compact" data-accounting-export="${kind}">${t('accountingExport_'+kind)}</button>`).join('');
  const integrations=profiles.map(x=>`<div class="row"><span><strong>${esc(x.label)}</strong><br><small class="muted">${t('integrationMode_'+x.mode)}</small></span><span class="pill ${x.status==='ready'?'good':'info'}">${t('integrationStatus_'+x.status)}</span></div>`).join('');
  return `<section class="artisan-page finance-artisan module-screen">${head(t('finance'))}
    ${moduleSectionNav([['overview',t('dashboard')],['analysis',t('indicators')],['accounting',t('accountingExports')],['entry',t('dailyEntry')]])}
    <div data-module-pane="overview">
      <div class="artisan-finance-hero"><span>${t('revenue')}</span><strong>${money(totals.revenue)}</strong><div class="chart">${series.map(x=>`<div class="chart-col"><div class="chart-track"><i style="height:${x.revenue?Math.max(8,x.revenue/max*100):2}%"></i></div><small>${esc(fmt(x))}</small></div>`).join('')}</div></div>
      <div class="grid artisan-finance-grid">${card(t('expenses'),`<div class="kpi">${money(totals.expenses)}</div>`)}${card(t('result'),`<div class="kpi">${money(totals.revenue-totals.expenses)}</div>`)}${card(t('covers'),`<div class="kpi">${totals.covers}</div>`)}</div>
    </div>
    <div data-module-pane="analysis">
      ${card(t('profitLeakCockpit'),`<div class="row"><span><strong>${t('estimatedExposure')}</strong><br><small class="muted">${cockpit.windowDays} ${t('days')} · ${cockpit.exposurePct}% ${t('ofRevenue')}</small></span><strong>${money(cockpit.totalExposure)}</strong></div>${leakRows}`)}
      ${benchmark.rows.length>1?card(t('multiSiteBenchmark'),`<div class="row"><span><strong>${t('networkAverage')}</strong><br><small class="muted">${benchmark.network.restaurants} ${t('restaurants')} · ${t('avgTicket')} ${money(benchmark.network.avgTicket)}</small></span><strong>${money(benchmark.network.revenue)}</strong></div>${benchmarkRows}`):''}
    </div>
    <div data-module-pane="accounting">
      ${card(t('accountingExports'),`<form id="accountingExportForm" class="form"><label class="document-field"><span>${t('fromDate')}</span><input name="from" type="date" value="${monthStart}" required></label><label class="document-field"><span>${t('toDate')}</span><input name="to" type="date" value="${selectedDate}" required></label><div class="actions">${exportButtons}</div></form><p class="muted">${t('accountingExportHint')}</p>`)}
      ${card(t('accountingIntegrations'),integrations)}
    </div>
    <div data-module-pane="entry">
      ${card(t('dailyEntry'),`<form id="financeForm" class="form"><input name="date" type="date" value="${selectedDate}" required><input name="revenue" type="number" step=".01" value="" placeholder="${t('revenue')}"><input name="covers" type="number" value="" placeholder="${t('covers')}"><input name="expenses" type="number" step=".01" value="" placeholder="${t('expenses')}"><button class="btn primary">${t('save')}</button></form><p class="muted finance-entry-hint">${t('financeEntryResetHint')}</p>${rows(state.financeHistory.slice(0,7),(x,i)=>`<div class="row"><span>${esc(x.date)}</span><span class="row-actions"><strong>${money(x.revenue)} · ${esc(x.covers)}</strong><button class="btn danger compact" data-remove="financeHistory" data-index="${i}">${t('clearManualEntry')}</button></span></div>`,'noFinanceHistory')}`)}
    </div>
  </section>`
}
const DOCUMENT_FIELDS={traceability:['product','lot','supplierName','quantity'],nonConformity:['issue','correctiveAction','responsible'],recipeSheet:['dish','ingredients','allergens'],purchaseOrder:['supplierName','product','quantity'],inspectionPrep:['area','task','responsible'],inventory:['product','quantity','location']};
const DOCUMENT_FIELDS_ALL={...DOCUMENT_FIELDS,haccpPlan:['area','hazard','preventiveMeasures','responsible'],temperatureRegister:['area','equipment','temperature','correctiveAction'],cleaningDisinfectionPlan:['area','cleaningTask','frequency','responsible'],allergenMatrix:['dish','allergens','ingredients'],productRecall:['product','lot','correctiveAction','responsible'],incidentReport:['incidentTitle','description','correctiveAction','responsible'],monthlyManagementReport:['revenue','covers','expenses','analysis']};
const DOCUMENT_TEXTAREAS=new Set(['issue','correctiveAction','ingredients','description','analysis','preventiveMeasures','salaryComponents','overtimeTerms','paidLeave','notice','pensionInsurance','trainingTerms','employerAddress','employeeAddress','workSchedule','functionDescription','terminationProcedure','restPeriods','breaks','shiftSystem','payrollNotes','certificateDuties','certificateAssessment','reason','returnOfProperty','expenseDescription','yearToDate','hoursVariation','benefits','mandatoryTraining','nonCompete']);
function documentSchema(type,country){if(isLegalHrDocument(type))return legalFieldsFor(type,country);return(DOCUMENT_FIELDS_ALL[type]||[]).map(key=>({key,section:'documentSection',type:DOCUMENT_TEXTAREAS.has(key)?'textarea':'text',required:false}))}
function documentFieldControl(def,value=''){const attrs=`${def.required?' required':''}${def.min!=null?` min="${esc(def.min)}"`:''}${def.step!=null?` step="${esc(def.step)}"`:''}`,name=`field_${def.key}`,label=`${t(def.key)}${def.required?' *':''}`,data=` data-doc-key="${esc(def.key)}" data-doc-section="${esc(def.section||'documentSection')}"`;if(def.type==='textarea')return `<label class="document-field"><span>${esc(label)}</span><textarea name="${name}" rows="3"${data}${attrs}>${esc(value)}</textarea></label>`;return `<label class="document-field"><span>${esc(label)}</span><input name="${name}" type="${def.type||'text'}" value="${esc(value)}"${data}${attrs}></label>`}
function documentFieldsForm(type,values={},country='CH'){const schema=documentSchema(type,country),preset={employerName:state.preferences?.restaurant||activeRestaurant(state)?.name||'',currency:state.preferences?.currency||activeRestaurant(state)?.currency||''},groups=new Map();for(const def of schema){const section=def.section||'documentSection';if(!groups.has(section))groups.set(section,[]);groups.get(section).push(def)}return[...groups.entries()].map(([section,defs])=>`<fieldset class="document-section"><legend>${esc(t(section))}</legend><div class="document-section-grid">${defs.map(def=>documentFieldControl(def,values?.[def.key]??preset[def.key]??'')).join('')}</div></fieldset>`).join('')}
function documentFieldsView(entry){const country=entry?.legal?.country||activeRestaurant(state)?.country||'CH',schema=documentSchema(entry.type,country),groups=new Map();for(const def of schema){const value=entry?.fields?.[def.key];if(value==null||String(value).trim()==='')continue;const section=def.section||'documentSection';if(!groups.has(section))groups.set(section,[]);groups.get(section).push([def,value])}return[...groups.entries()].map(([section,items])=>`<section class="document-preview-section"><h5>${esc(t(section))}</h5>${items.map(([def,value])=>`<div class="document-detail-row"><strong>${esc(t(def.key))}</strong><span class="document-details">${esc(value)}</span></div>`).join('')}</section>`).join('')}
function documentLegalBanner(entryOrPack){const pack=entryOrPack?.source?entryOrPack:legalPack(entryOrPack?.legal?.country||activeRestaurant(state)?.country||'CH');return `<aside class="legal-pack"><div><strong>${esc(pack.name||entryOrPack?.legal?.name||'')}</strong><span>${t('legalPack')}</span></div><p>${esc(pack.source||entryOrPack?.legal?.source||'')}</p><small>${t('legalReviewed')} ${esc(pack.reviewedAt||entryOrPack?.legal?.reviewedAt||'')} · ${esc(pack.note||entryOrPack?.legal?.note||'')}</small></aside>`}
function documents(){const selected=editing?.collection==='document'?editing.type:null,entry=editing?.index>=0?state.documentEntries?.[editing.index]:null,preview=editing?.collection==='documentPreview'?state.documentEntries?.[editing.index]:null,hr=new Set(['payslip','employmentContract','extraContract','salaryCertificate','timesheet','leaveRequest','employmentCertificate','employmentTermination','onboardingChecklist','salaryChange','expenseReport','trainingRecord']),quality=new Set(['haccpPlan','temperatureRegister','cleaningDisinfectionPlan','allergenMatrix','traceability','nonConformity','productRecall','incidentReport','inspectionPrep']),currentPack=legalPack(legalCountryOverride||activeRestaurant(state)?.country||'CH'),selectedPack=selected&&isLegalHrDocument(selected)?legalPack(entry?.legal?.country||currentPack.code):null,tile=k=>`<button class="doc-tile" data-doc-fill="${k}">${icon('documents')}<span><strong>${t(k)}</strong><small>${hr.has(k)?currentPack.name:t('fill')}</small></span><b>›</b></button>`,hrDocs=state.docs.filter(k=>hr.has(k)),qualityDocs=state.docs.filter(k=>quality.has(k)),otherDocs=state.docs.filter(k=>!hr.has(k)&&!quality.has(k));
if(selected)return `<section class="artisan-page documents-artisan document-workspace">${head(t(selected),'documents')}<div class="document-fullpage">${selectedPack?documentLegalBanner(selectedPack):''}<form id="documentForm" class="form document-legal-form"><input type="hidden" name="type" value="${esc(selected)}"><input type="hidden" name="legalCountry" value="${esc(selectedPack?.code||'')}"><div class="document-base-fields"><label class="document-field"><span>${t('date')}</span><input name="date" type="date" value="${esc(entry?.date||today())}" required></label><label class="document-field"><span>${t('documentTitle')} *</span><input name="title" required value="${esc(entry?.title||'')}"></label></div>${documentFieldsForm(selected,entry?.fields,selectedPack?.code||currentPack.code)}${selected==='payslip'?`<div class="payroll-live-summary"><div class="payroll-verification-banner ${swissPayrollVerification(state).verified?'verified':'blocked'}" data-payroll-blocker><strong>${swissPayrollVerification(state).verified?t('payrollSettingsVerified'):t('payrollVerificationRequired')}</strong><span>${swissPayrollVerification(state).verified?t('payrollExportAllowed'):t('payrollVerificationBlockingHint')}</span></div><div><span>${t('calculatedGross')}</span><strong data-payroll-gross>—</strong></div><div><span>${t('enteredDeductions')}</span><strong data-payroll-deductions>—</strong></div><div><span>${t('indicativeNet')}</span><strong data-payroll-net>—</strong></div><div><span>${t('employerContributions')}</span><strong data-payroll-employer>—</strong></div><button type="button" id="applyPayrollTotals" class="btn" ${swissPayrollVerification(state).verified?'':'disabled'}>${t('applyCalculatedTotals')}</button><p class="muted" data-payroll-warnings></p><p class="muted">${t('payrollCalculationHint')}</p></div>`:''}<label class="document-field document-notes"><span>${t('documentDetails')}</span><textarea name="details" rows="5">${esc(entry?.details||'')}</textarea></label><div class="document-page-actions"><button class="btn primary">${t('save')}</button><button type="button" class="btn" data-cancel-edit>${t('back')}</button></div></form></div></section>`;
if(preview)return `<section class="artisan-page documents-artisan document-workspace">${head(t('preview'),'documents')}<div class="document-fullpage"><article class="document-preview document-preview-full"><h3>${esc(state.preferences?.restaurant||'ReMaPro Hub')}</h3><p class="muted">${esc(t(preview.type))} · ${esc(preview.date)}</p>${preview.legal?documentLegalBanner({source:preview.legal.source,name:preview.legal.name,reviewedAt:preview.legal.reviewedAt,note:preview.legal.note}):''}<h4>${esc(preview.title)}</h4>${documentFieldsView(preview)}<p class="document-details">${esc(preview.details)}</p>${preview.type==='payslip'&&preview.legal?.country==='CH'&&!swissPayrollVerification(state).verified?`<div class="payroll-verification-banner blocked"><strong>${t('payrollExportBlocked')}</strong><span>${t('payrollVerificationBlockingHint')}</span></div>`:''}<div class="document-page-actions"><button class="btn primary" data-doc-download="${editing.index}" ${preview.type==='payslip'&&preview.legal?.country==='CH'&&!swissPayrollVerification(state).verified?'disabled':''}>${t('download')}</button><button class="btn" data-cancel-edit>${t('back')}</button></div></article></div></section>`;
return `<section class="artisan-page documents-artisan">${head(t('documents'))}<div class="artisan-hero artisan-doc-hero"><div class="artisan-hero-mark">${icon('documents')}</div><div><span class="artisan-eyebrow">${t('documents')}</span><h2>${t('documentHistory')}</h2><p>${state.documentEntries?.length||0}</p></div></div>${documentLegalBanner(currentPack)}<div class="legal-country-picker"><label><span>${t('legalCountry')}</span><select id="documentLegalCountry" class="lang">${LEGAL_COUNTRIES.map(x=>`<option value="${x.code}" ${x.code===currentPack.code?'selected':''}>${esc(x.name)}</option>`).join('')}${currentPack.code==='GENERIC'?'<option value="GENERIC" selected>International / générique</option>':''}</select></label></div><div class="document-groups">${hrDocs.length?`<section class="document-group"><h2>${t('hrTools')}</h2><p class="muted">${t('legalCountry')}: ${esc(currentPack.name)}</p>${hrDocs.map(tile).join('')}</section>`:''}${qualityDocs.length?`<section class="document-group"><h2>${t('haccp')}</h2>${qualityDocs.map(tile).join('')}</section>`:''}${otherDocs.length?`<section class="document-group"><h2>${t('operations')}</h2>${otherDocs.map(tile).join('')}</section>`:''}</div>${card(t('documentHistory'),rows(state.documentEntries||[],(x,i)=>`<div class="row"><span><strong>${esc(t(x.type))}</strong><br><small class="muted">${esc(x.date)} · ${esc(x.title)}${x.legal?.name?` · ${esc(x.legal.name)}`:''}</small><br><small class="document-details">${esc(x.details)}</small></span><span class="row-actions"><button class="btn compact" data-doc-preview="${i}">${t('preview')}</button><button class="btn compact" data-doc-edit="${i}">${t('edit')}</button><button class="btn compact" data-doc-download="${i}">${t('download')}</button><button class="btn danger compact" data-remove="documentEntries" data-index="${i}">${t('delete')}</button></span></div>`,'noDocuments'))}</section>`}

function deliveryScannerCard(){
  const scan=deliveryScanState,photos=scan.photos||[],analysis=scan.analysis,items=Array.isArray(analysis?.items)?analysis.items:[];
  const stockOptions=selected=>`<option value="__new__" ${!selected?'selected':''}>+ ${t('newProduct')}</option>${state.stock.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)} · ${esc(x.unit||'')}</option>`).join('')}`;
  const photosHtml=photos.length?`<div class="delivery-photo-grid">${photos.map((p,i)=>`<figure class="delivery-photo"><img src="${esc(p.preview)}" alt="Photo ${i+1}"><figcaption><span>${esc(p.name)}</span>${!analysis?`<button type="button" class="btn compact danger" data-delivery-photo-remove="${esc(p.id)}">×</button>`:''}</figcaption></figure>`).join('')}</div>`:`<p class="muted">${t('addDeliveryPhotos')}</p>`;
  const progress=scan.busy?`<div class="delivery-progress-wrap"><div class="delivery-progress"><span style="width:${Math.max(2,Math.min(100,Number(scan.progress)||0))}%"></span></div><small>${scan.stage==='upload'?t('securePhotoUpload'):scan.stage==='analysis'?t('deliveryRecognitionProgress'):t('processing')} ${Math.round(Number(scan.progress)||0)}%</small></div>`:'';
  const review=analysis?`<form id="deliveryScanReviewForm" class="delivery-review-form">
    <div class="delivery-review-head"><div><h3>${t('reviewDelivery')}</h3><p class="muted">${items.length} produit(s) détecté(s) · ${analysis.summary?.matched||0} associé(s) au catalogue · ${analysis.summary?.uncertain||0} à vérifier</p></div><span class="pill info">Analyse ${esc(String(analysis.analysisId||scan.analysisId).slice(0,8))}</span></div>
    <div class="form delivery-meta"><input name="supplier" placeholder="Fournisseur"><input name="date" type="date" value="${today()}" required></div>
    <div class="delivery-result-list">${items.length?items.map((x,i)=>{
      const conf=Math.max(0,Math.min(1,Number(x.confidence)||0)),band=confidenceBand(conf),matched=x.match?.stockId||'',evidence=[...(x.evidence?.ocr||[]),...(x.evidence?.visual||[])].slice(0,3);
      return `<article class="delivery-result ${band}">
        <div class="delivery-result-title"><label><input type="checkbox" name="scan_use_${i}" checked> <strong>${esc(x.name||'Produit non identifié')}</strong></label><span class="delivery-confidence ${band}">${confidenceLabel(conf,language())} · ${Math.round(conf*100)}%</span></div>
        <div class="delivery-result-grid">
          <label>${t('remaproProduct')}<select name="scan_stock_${i}">${stockOptions(matched)}</select></label>
          <label>${t('detectedProduct')}<input name="scan_name_${i}" value="${esc(x.name||'')}" required></label>
          <label>${t('brand')}<input name="scan_brand_${i}" value="${esc(x.brand||'')}"></label>
          <label>${t('packaging')}<input name="scan_packaging_${i}" value="${esc(x.packaging||'')}"></label>
          <label>Quantité<input name="scan_qty_${i}" type="number" min="0.001" step="0.001" value="${esc(x.quantity||1)}" required></label>
          <label>Unité<input name="scan_unit_${i}" value="${esc(x.unit||'unité')}" required></label>
          <label>${t('barcode')}<input name="scan_barcode_${i}" value="${esc(x.barcode||'')}"></label>
        </div>
        <div class="delivery-result-meta">${x.match?`Association : <strong>${esc(x.match.name)}</strong> · ${Math.round((Number(x.match.confidence)||0)*100)}%`:`<strong>${t('noCatalogMatch')}</strong>`}${evidence.length?`<br><small>${t('evidence')} : ${evidence.map(esc).join(' · ')}</small>`:''}</div>
        ${conf<.7?`<label class="delivery-required-check"><input type="checkbox" name="scan_confirm_${i}"> ${t('manualReviewConfirm')}</label>`:''}
      </article>`;
    }).join(''):`<div class="notice warning">${t('unidentifiedDelivery')}</div>`}</div>
    <div class="actions"><button class="btn primary" ${!items.length||scan.busy?'disabled':''}>${t('validateDeliveryFinal')}</button><button type="button" id="deliveryScanCancel" class="btn" ${scan.busy?'disabled':''}>${t('cancelAnalysis')}</button></div>
    <p class="muted">${t('noStockBeforeValidation')}</p>
  </form>`:'';
  return card(t('deliveryEntries'),`<div class="delivery-scanner"><div class="delivery-scan-head"><div><h3>${t('scanDelivery')}</h3><p class="muted">${t('deliveryScannerHint')}</p></div><span class="pill">${t('deliveryAiMulti')}</span></div>
    <div class="actions"><button type="button" id="deliveryScanCamera" class="btn">📷 ${t('takePhoto')}</button><button type="button" id="deliveryScanGallery" class="btn">🖼️ ${t('gallery')}</button><input id="deliveryScanFileInput" type="file" accept="image/*" multiple hidden></div>
    ${photosHtml}
    ${!analysis?`<div class="actions"><button type="button" id="deliveryScanAnalyze" class="btn primary" ${!photos.length||scan.busy?'disabled':''}>${t('analyzePhotos')} ${photos.length?photos.length:''}</button><small class="muted">${DELIVERY_AI_MAX_PHOTOS} ${t('maxPhotosHint')}</small></div>`:''}
    ${progress}${scan.error?`<div class="notice error">${esc(scan.error)}</div>`:''}${review}
  </div>`);
}
function resetDeliveryScanner(){
  disposeDeliveryPhotos(deliveryScanState.photos||[]);
  deliveryScanState={photos:[],analysis:null,analysisId:'',paths:[],busy:false,progress:0,stage:'',error:''};
}
function addDeliveryScanPhotos(entries){
  const current=deliveryScanState.photos||[],seen=new Set(current.map(x=>`${x.name}|${x.size}`));
  for(const p of entries||[]){const key=`${p.name}|${p.size}`;if(current.length>=DELIVERY_AI_MAX_PHOTOS){if(p.preview)URL.revokeObjectURL(p.preview);continue}if(seen.has(key)){if(p.preview)URL.revokeObjectURL(p.preview);continue}seen.add(key);current.push(p)}
  deliveryScanState.photos=current;deliveryScanState.error='';render();
}
function bindDeliveryScanner(){
  const input=document.getElementById('deliveryScanFileInput');
  input?.addEventListener('change',e=>{const files=e.currentTarget.files;e.currentTarget.value='';try{addDeliveryScanPhotos(photosFromFiles(files))}catch{deliveryScanState.error=t('deliveryPhotoReadFailed');render()}});
  document.getElementById('deliveryScanGallery')?.addEventListener('click',async()=>{
    try{const native=await pickDeliveryPhotos();if(native)addDeliveryScanPhotos(native);else if(input){input.removeAttribute('capture');input.multiple=true;input.click()}}catch{deliveryScanState.error=t('galleryOpenFailed');render()}
  });
  document.getElementById('deliveryScanCamera')?.addEventListener('click',async()=>{
    try{const photo=await takeDeliveryPhoto();if(photo)addDeliveryScanPhotos([photo]);else if(input){input.setAttribute('capture','environment');input.multiple=false;input.click()}}catch{deliveryScanState.error=t('cameraOpenFailed');render()}
  });
  document.querySelectorAll('[data-delivery-photo-remove]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.deliveryPhotoRemove,p=deliveryScanState.photos.find(x=>x.id===id);if(p?.preview)URL.revokeObjectURL(p.preview);deliveryScanState.photos=deliveryScanState.photos.filter(x=>x.id!==id);render()}));
  document.getElementById('deliveryScanAnalyze')?.addEventListener('click',async()=>{
    const rid=cloudRestaurantId();if(!rid){alert(t('cloudRestaurantRequired'));return}if(!cloudSession()){alert(t('cloudLoginRequired'));return}
    const photos=deliveryScanState.photos||[];if(!photos.length)return;
    deliveryScanState.analysisId=deliveryScanState.analysisId||globalThis.crypto?.randomUUID?.()||String(Date.now());
    deliveryScanState.busy=true;deliveryScanState.progress=2;deliveryScanState.stage='upload';deliveryScanState.error='';render();
    try{
      const result=await analyzeDeliveryPhotos({restaurantId:rid,analysisId:deliveryScanState.analysisId,photos,language:language(),onProgress:(progress,stage)=>{deliveryScanState.progress=progress;deliveryScanState.stage=stage;const bar=document.querySelector('.delivery-progress span');if(bar)bar.style.width=progress+'%';const label=document.querySelector('.delivery-progress-wrap small');if(label)label.textContent=(stage==='analysis'?'Reconnaissance visuelle, OCR et codes-barres… ':'Envoi sécurisé… ')+progress+'%'}});
      deliveryScanState.paths=result.paths||[];deliveryScanState.analysis=result.data;deliveryScanState.busy=false;deliveryScanState.progress=100;deliveryScanState.stage='done';
      if(!result.data?.items?.length)deliveryScanState.error='L’IA n’a pas pu identifier un produit avec suffisamment d’éléments. Essayez une photo plus nette.';
      render();
    }catch(error){deliveryScanState.busy=false;deliveryScanState.error=error?.message||t('deliveryAnalysisRetry');render()}
  });
  document.getElementById('deliveryScanCancel')?.addEventListener('click',async()=>{
    const rid=cloudRestaurantId(),analysisId=deliveryScanState.analysisId;
    if(analysisId&&deliveryScanState.analysis&&rid)try{await cancelDeliveryAnalysis(rid,analysisId,deliveryScanState.paths||[])}catch{}
    resetDeliveryScanner();render();
  });
  document.getElementById('deliveryScanReviewForm')?.addEventListener('submit',async e=>{
    e.preventDefault();if(deliveryScanState.busy)return;
    const form=new FormData(e.currentTarget),source=deliveryScanState.analysis?.items||[],items=[];
    for(let i=0;i<source.length;i++){
      if(form.get('scan_use_'+i)!=='on')continue;
      const confidence=Number(source[i].confidence)||0;
      if(confidence<.7&&form.get('scan_confirm_'+i)!=='on'){alert(t('confirmRedResults'));return}
      const selected=String(form.get('scan_stock_'+i)||''),quantity=Number(form.get('scan_qty_'+i)),name=String(form.get('scan_name_'+i)||'').trim(),unit=String(form.get('scan_unit_'+i)||'').trim();
      if(!name||!unit||!Number.isFinite(quantity)||quantity<=0){alert(t('deliveryFieldsInvalid'));return}
      const stockId=selected&&selected!=='__new__'?selected:'';
      if(stockId&&!state.stock.some(x=>String(x.id)===stockId)){alert(t('stockReferenceGone'));return}
      items.push({use:true,stockId,name,brand:String(form.get('scan_brand_'+i)||''),packaging:String(form.get('scan_packaging_'+i)||''),quantity,unit,barcode:String(form.get('scan_barcode_'+i)||''),confidence,matchConfidence:Number(source[i].match?.confidence)||0});
    }
    if(!items.length){alert('Sélectionnez au moins un produit.');return}
    const corrected={supplier:String(form.get('supplier')||'').trim(),date:String(form.get('date')||today()),items};
    deliveryScanState.busy=true;deliveryScanState.stage='validation';deliveryScanState.progress=95;render();
    try{
      await finalizeDeliveryAnalysis(cloudRestaurantId(),deliveryScanState.analysisId,corrected);
      const applied=applyDeliveryAiReceiving(state,{analysisId:deliveryScanState.analysisId,supplier:corrected.supplier,date:corrected.date,items});
      if(!applied)throw new Error('Impossible d’appliquer cette livraison au stock.');
      persist();const count=applied.movements,created=applied.createdProducts;resetDeliveryScanner();render();alert(`Livraison validée : ${count} mouvement(s) d’entrée${created?` · ${created} nouveau(x) produit(s)`:''}.`);
    }catch(error){deliveryScanState.busy=false;deliveryScanState.error=error?.message||t('deliveryValidationFailed');render()}
  });
}
function stock(){const supplierOptions=selected=>`<option value="">${t('noPreferredSupplier')}</option>${state.suppliers.map(x=>`<option value="${esc(x.name)}" ${x.name===selected?'selected':''}>${esc(x.name)}</option>`).join('')}`,reorders=reorderSuggestions(state),priceAlerts=supplierPriceAlerts(state),intelligence=`<div class="grid intelligence-grid">${card(t('reorderSuggestions'),reorders.length?reorders.slice(0,8).map(x=>`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${t('available')}: ${esc(x.available)} ${esc(x.unit)} · ${t('reorderPoint')}: ${esc(x.reorderPoint)} · ${t('avgDailyUsage')}: ${esc(x.avgDaily)}${x.daysCover!=null?' · '+t('daysCover')+': '+esc(x.daysCover):''}</small></span><span><strong>${t('quantityToOrder')}: ${esc(x.quantity)} ${esc(x.unit)}</strong><br><small class="muted">${t('leadTime')}: ${esc(x.leadTimeDays)} ${t('days')} · ${t('safetyStockDays')}: ${esc(x.safetyDays)} · ≈ ${money(x.estimatedCost)}</small></span></div>`).join(''):`<p class="muted">✓ ${t('noPriority')}</p>`)}${priceAlerts.length?card(t('supplierPriceChanges'),priceAlerts.slice(0,8).map(x=>`<div class="row"><span><strong>${esc(x.product)}</strong><br><small class="muted">${esc(x.supplier)} · ${esc(x.date)}</small></span><span class="pill ${x.changePct>0?'warning':'good'}">${x.changePct>0?'+':''}${esc(x.changePct)}%</span></div>`).join('')):''}</div>`;return `<section class="artisan-page stock-artisan module-screen">${head(t('stock'))}
  ${moduleSectionNav([['inventory',t('inventory')],['count',t('inventoryCount')],['receiving',t('deliveryEntries')],['intelligence',t('reorderSuggestions')]])}
  <div data-module-pane="inventory">${card(t('inventory'),`<form id="stockForm" class="form"><input name="name" required placeholder="${t('product')}"><input name="unit" placeholder="${t('unit')}"><input name="barcode" placeholder="${t('barcode')}"><input name="qty" required type="number" step=".01" min="0" placeholder="${t('baseQuantity')}"><input name="price" type="number" min="0" step=".01" placeholder="${t('purchasePrice')}"><input name="min" type="number" step=".01" min="0" placeholder="${t('minimumStock')}"><input name="reorderTarget" type="number" step=".01" min="0" placeholder="${t('targetStock')}"><input name="safetyDays" type="number" min="0" max="60" step="1" value="2" placeholder="${t('safetyStockDays')}"><select name="preferredSupplier" aria-label="${t('preferredSupplier')}">${supplierOptions('')}</select><button class="btn primary">${t('add')}</button></form>${rows(state.stock,(x,i)=>editingRow('stock',i)?`<form class="form inline-edit" data-edit-form="stock" data-index="${i}"><input name="name" required value="${esc(x.name)}"><input name="unit" value="${esc(x.unit||'')}" placeholder="${t('unit')}"><input name="barcode" value="${esc(x.barcode||'')}" placeholder="${t('barcode')}"><input name="qty" required type="number" step=".01" min="0" value="${esc(x.qty)}"><input name="price" type="number" min="0" step=".01" value="${esc(x.price)}"><input name="min" type="number" step=".01" min="0" value="${esc(x.min||0)}"><input name="reorderTarget" type="number" step=".01" min="0" value="${esc(x.reorderTarget||0)}" placeholder="${t('targetStock')}"><input name="safetyDays" type="number" min="0" max="60" step="1" value="${esc(x.safetyDays??2)}" placeholder="${t('safetyStockDays')}"><select name="preferredSupplier" aria-label="${t('preferredSupplier')}">${supplierOptions(x.preferredSupplier||'')}</select>${editButtons()}</form>`:`<div class="row"><span>${esc(x.name)}<br><small class="muted">${esc(x.unit||'')}${x.barcode?' · '+t('barcode')+': '+esc(x.barcode):''}</small></span><span class="row-actions"><strong>${t('available')}: ${esc(stockAvailable(state,x))} ${esc(x.unit||'')} · ${money(x.price)}</strong><small>${t('baseQuantity')}: ${esc(x.qty)} ${esc(x.unit||'')}${(+x.reorderTarget||0)>0?` · ${t('targetStock')}: ${esc(x.reorderTarget)} ${esc(x.unit||'')}`:''} · ${t('safetyStockDays')}: ${esc(x.safetyDays??2)}${x.preferredSupplier?` · ${t('preferredSupplier')}: ${esc(x.preferredSupplier)}`:''}</small>${(+x.min||0)>0&&stockAvailable(state,x)<=+(x.min||0)?`<span class="pill warning">${t('lowStock')}</span>`:''}${actions('stock',i)}</span></div>`,'noStock')}`)}</div>
  <div data-module-pane="count">${inventoryCountPanel()}</div>
  <div data-module-pane="receiving">${deliveryScannerCard()}${card(t('stockPhoto'),`<div class="form"><input id="stockPhotoInput" type="file" accept="image/*" capture="environment"><button type="button" id="stockPhotoAnalyze" class="btn primary">${t('analyzePhoto')}</button></div><p class="muted">${t('aiHint')}</p>`)}${visionDraft?card(t('photoResult'),`<form id="visionStockForm" class="form"><input name="name" required value="${esc(visionDraft.name||'')}" placeholder="${t('product')}"><input name="unit" value="${esc(visionDraft.unit||'')}" placeholder="${t('unit')}"><input name="barcode" value="${esc(visionDraft.barcode||visionDraft.sku||'')}" placeholder="${t('barcode')}"><input name="qty" required type="number" step=".01" min="0" value="${esc(visionDraft.quantity??1)}" placeholder="${t('baseQuantity')}"><input name="price" type="number" min="0" step=".01" value="${esc(visionDraft.unitCost??0)}" placeholder="${t('purchasePrice')}"><input name="min" type="number" step=".01" min="0" value="0" placeholder="${t('minimumStock')}"><input name="reorderTarget" type="number" step=".01" min="0" value="0" placeholder="${t('targetStock')}"><input name="safetyDays" type="number" min="0" max="60" step="1" value="2" placeholder="${t('safetyStockDays')}"><select name="preferredSupplier" aria-label="${t('preferredSupplier')}">${supplierOptions('')}</select><button class="btn primary">${t('add')}</button></form><p class="muted">${t('confidence')}: ${esc(Math.round((+visionDraft.confidence||0)*100))}%</p>`):''}</div>
  <div data-module-pane="intelligence">${intelligence}</div>
</section>`}
function suppliers(){return `<section>${head(t('suppliers'))}${card(t('suppliers'),`<form id="supplierForm" class="form"><input name="name" required placeholder="${t('supplierName')}"><input name="contact" placeholder="${t('contact')}"><label class="document-field"><span>${t('paymentTermsDays')}</span><input name="paymentDays" type="number" min="0" max="180" step="1" value="30"></label><label class="document-field"><span>${t('supplierLeadTime')}</span><input name="leadTimeDays" type="number" min="0" max="90" step="1" value="3"></label><button class="btn primary">${t('add')}</button></form><p class="muted">${t('paymentTermsHint')}</p>${rows(state.suppliers,(x,i)=>editingRow('suppliers',i)?`<form class="form inline-edit" data-edit-form="suppliers" data-index="${i}"><input name="name" required value="${esc(x.name)}"><input name="contact" value="${esc(x.contact)}"><input name="paymentDays" type="number" min="0" max="180" step="1" value="${esc(x.paymentDays??30)}"><input name="leadTimeDays" type="number" min="0" max="90" step="1" value="${esc(x.leadTimeDays??3)}">${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.contact)} · ${t('paymentTermsShort')}: ${esc(x.paymentDays??30)} ${t('days')} · ${t('leadTime')}: ${esc(x.leadTimeDays??3)} ${t('days')}</small></span>${actions('suppliers',i)}</div>`,'noSuppliers')}`)}</section>`}
function team(){return `<section class="artisan-page module-screen">${head(t('team'))}${moduleSectionNav([['people',t('team')],['planning',t('planning')],['documents',t('documents')]])}<div data-module-pane="people">${card(t('team'),`<form id="teamForm" class="form"><input name="name" required placeholder="${t('employeeName')}"><input name="role" placeholder="${t('role')}"><input name="hourlyRate" type="number" min="0" max="500" step=".05" placeholder="${t('hourlyRate')}"><button class="btn primary">${t('add')}</button></form>${rows(state.team,(x,i)=>editingRow('team',i)?`<form class="form inline-edit" data-edit-form="team" data-index="${i}"><input name="name" required value="${esc(x.name)}"><input name="role" value="${esc(x.role)}"><input name="hourlyRate" type="number" min="0" max="500" step=".05" value="${esc(x.hourlyRate||0)}">${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.role)} · ${t('hourlyRate')} ${money(+x.hourlyRate||0)}/h</small></span>${actions('team',i)}</div>` ,'noTeam')}`)}</div><div data-module-pane="planning">${card(t('planning'),`<button class="btn primary" data-page="planning">${t('planning')}</button>`)}</div><div data-module-pane="documents">${card(t('documents'),`<button class="btn primary" data-page="documents">${t('documents')}</button>`)}</div></section>`}
function workforcePanel(){
  const actual=actualLabor(state),variance=workforceVariance(state),forecast=laborForecast(state),availabilityIssues=availabilityConflicts(state),pendingSwaps=(state.shiftSwaps||[]).filter(x=>x.status==='requested');
  const forecastRows=forecast.rows.map(x=>{const signal=x.signals?.length?x.signals.map(s=>`${t('forecastSignal_'+s.type)} ${s.impactPct>0?'+':''}${s.impactPct}%`).join(' · '):'',season=Math.abs((x.seasonFactor||1)-1)>=.03?`${t('seasonality')} ×${x.seasonFactor}`:'',basis=[`${x.historySamples} ${t('historySamples')}`,season,signal,`${t('reservedCovers')}: ${x.reservedCovers}`].filter(Boolean).join(' · ');return `<div class="row"><span><strong>${esc(x.date)}</strong><br><small class="muted">${x.forecastCovers} ${t('covers')} · ${money(x.forecastRevenue)}<br>${esc(basis)}</small></span><span class="row-actions"><strong>${x.recommendedStaff} ${t('recommendedStaff')} · ${x.recommendedHours}h</strong><span class="pill ${x.gap>1?'warning':x.gap<-2?'info':'good'}">${t('scheduledHours')}: ${x.scheduledHours}h · ${x.gap>0?'+':''}${x.gap}h</span></span></div>`}).join('');
  const clockRows=(state.timeClock||[]).slice(0,12).map(x=>{const start=new Date(x.clockIn),end=x.clockOut?new Date(x.clockOut):new Date(),breakMin=(x.breaks||[]).reduce((sum,b)=>{const pa=new Date(b.start),pb=b.end?new Date(b.end):new Date();return sum+(!Number.isNaN(pa.getTime())&&!Number.isNaN(pb.getTime())&&pb>pa?(pb-pa)/60000:0)},0),hours=Math.max(0,(end-start)/3600000-breakMin/60);return `<div class="row"><span><strong>${esc(x.employee)}</strong><br><small class="muted">${esc(x.clockIn.slice(0,16).replace('T',' '))}${x.clockOut?' → '+esc(x.clockOut.slice(11,16)):' · '+t('clockActive')}</small></span><span class="pill ${x.status==='open'?'warning':'good'}">${hours.toFixed(2)} h</span></div>`}).join('')||`<p class="muted">${t('noTimeClock')}</p>`;
  const varianceRows=variance.rows.slice(0,14).map(x=>`<div class="row"><span><strong>${esc(x.employee)} · ${esc(x.date)}</strong><br><small class="muted">${t('plannedVsActual')}: ${x.plannedHours}h → ${x.actualHours}h · ${t('actualCost')}: ${money(x.actualCost)}</small></span><span class="row-actions">${x.lateMinutes>=5?'<span class="pill warning">'+t('late')+' '+x.lateMinutes+' min</span>':''}${x.extraVsPlanHours>0?'<span class="pill info">+'+x.extraVsPlanHours+'h '+t('extraHours')+'</span>':''}${x.missingClockIn?'<span class="pill bad">'+t('missingClockIn')+'</span>':''}</span></div>`).join('')||`<p class="muted">${t('noTimeClock')}</p>`;
  const availabilityRows=(state.availability||[]).slice(0,10).map((x,i)=>`<div class="row"><span><strong>${esc(x.employee)}</strong><br><small class="muted">${esc(x.date)} ${esc(x.start||'')}–${esc(x.end||'')} · ${t('availability_'+x.status)}</small></span><button class="btn danger compact" data-remove="availability" data-index="${i}">${t('delete')}</button></div>`).join('')||`<p class="muted">${t('noAvailability')}</p>`;
  const swaps=pendingSwaps.map(x=>`<div class="row"><span><strong>${esc(x.fromEmployee)} → ${esc(x.toEmployee)}</strong><br><small class="muted">${esc(x.date)} · ${esc(x.start)}–${esc(x.end)}</small></span><span class="row-actions"><button type="button" class="btn compact primary" data-swap-resolve="${x.id}" data-swap-status="approved">${t('approve')}</button><button type="button" class="btn compact" data-swap-resolve="${x.id}" data-swap-status="refused">${t('refuse')}</button></span></div>`).join('')||`<p class="muted">${t('noShiftSwaps')}</p>`;
  const forecastSignals=(state.forecastSignals||[]).slice(0,10).map((x,i)=>`<div class="row"><span><strong>${esc(x.date)} · ${t('forecastSignal_'+x.type)}</strong><br><small class="muted">${x.impactPct>0?'+':''}${esc(x.impactPct)}% · ${esc(x.note||'')}</small></span><button class="btn danger compact" data-remove="forecastSignals" data-index="${i}">${t('delete')}</button></div>`).join('')||`<p class="muted">${t('noForecastSignals')}</p>`;
  return `<div class="grid intelligence-grid workforce-kpis">${card(t('actualLabor'),`<div class="kpi mini">${actual.hours} h</div><small>${t('actualCost')}: ${money(actual.cost)} · ${t('clockActive')}: ${actual.open}</small>`)}${card(t('plannedVsActual'),`<div class="kpi mini">${variance.varianceHours>0?'+':''}${variance.varianceHours} h</div><small>${t('plannedCost')}: ${money(variance.plannedCost)} · ${t('actualCost')}: ${money(variance.actualCost)}</small>`)}${card(t('overtime'),`<div class="kpi mini">${variance.weeklyOvertimeHours} h</div><small>${t('lateArrivals')}: ${variance.lateArrivals} · ${t('missingClockIn')}: ${variance.missingClockIns}</small>`)}${card(t('laborForecast'),`<div class="kpi mini">${forecast.understaffed}</div><small>${t('understaffedDays')} · ${forecast.overstaffed} ${t('overstaffedDays')}</small>`)}</div>
  ${card(t('timeClock'),`<div class="form inline-workforce"><select id="timeClockEmployee"><option value="">${t('employeeName')}</option>${state.team.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+'</option>').join('')}</select><button type="button" class="btn primary" data-clock-action="in">${t('clockIn')}</button><button type="button" class="btn" data-clock-action="break">${t('break')}</button><button type="button" class="btn" data-clock-action="out">${t('clockOut')}</button></div>${clockRows}`)}
  ${card(t('laborVariance'),varianceRows)}
  ${card(t('laborForecast'),forecastRows)}
  ${card(t('forecastSignals'),`<form id="forecastSignalForm" class="form"><input name="date" type="date" required><select name="type"><option value="weather">${t('forecastSignal_weather')}</option><option value="event">${t('forecastSignal_event')}</option><option value="manual">${t('forecastSignal_manual')}</option></select><input name="impactPct" type="number" min="-50" max="100" step="1" value="0" placeholder="${t('impactPct')}"><input name="note" placeholder="${t('note')}"><button class="btn primary">${t('add')}</button></form>${forecastSignals}`)}
  ${availabilityIssues.count?'<div class="notice warning">'+t('availabilityConflict')+' · '+availabilityIssues.count+'</div>':''}
  ${card(t('availability'),`<form id="availabilityForm" class="form"><select name="employee" required>${teamOptions('')}</select><input name="date" type="date" required><input name="start" type="time"><input name="end" type="time"><select name="status"><option value="available">${t('availability_available')}</option><option value="preferred">${t('availability_preferred')}</option><option value="unavailable">${t('availability_unavailable')}</option></select><input name="note" placeholder="${t('note')}"><button class="btn primary">${t('add')}</button></form>${availabilityRows}`)}
  ${card(t('shiftSwap'),`<form id="shiftSwapForm" class="form"><select name="shiftIndex" required><option value="">${t('selectShift')}</option>${state.shifts.map((x,i)=>'<option value="'+i+'">'+esc(x.date+' · '+x.employee+' '+x.start+'–'+x.end)+'</option>').join('')}</select><select name="toEmployee" required>${teamOptions('')}</select><input name="note" placeholder="${t('note')}"><button class="btn primary">${t('requestSwap')}</button></form>${swaps}`)}
  ${card(t('leaveMobile'),`<div class="row"><span><strong>${t('leaveMobile')}</strong><br><small class="muted">${t('leaveMobileHint')}</small></span><button type="button" class="btn primary" data-page="leave">${t('leaveRequest')}</button></div>`)}
  `;
}
