function purchases(){const total=(state.purchases||[]).reduce((s,x)=>s+(+x.amount||0),0),plan=buildPurchasePlan(state),opportunities=supplierPriceOpportunities(state),recipeImpacts=recipeSupplierImpacts(state),draftItems=Array.isArray(invoiceDraft?.items)?invoiceDraft.items:[];return `<section>${head(t('purchases'))}${purchaseOrderPanel()}<div class="grid">${card(t('purchases'),`<div class="kpi">${money(total)}</div>`)}${card(t('suppliers'),`<div class="kpi">${state.suppliers.length}</div>`)}</div>${card(t('purchasePlan'),plan.groups.length?`<div class="purchase-plan-summary"><strong>${t('estimatedReorderBudget')}: ${money(plan.estimatedCost)}</strong>${plan.unassignedItems?`<span class="pill warning">${t('supplierToAssign')}: ${plan.unassignedItems}</span>`:''}</div>${plan.groups.map((group,groupIndex)=>`<div class="row"><span><strong>${esc(group.supplier||t('supplierToAssign'))}</strong><br><small class="muted">${group.items.map(x=>`${esc(x.name)} · ${esc(x.quantity)} ${esc(x.unit)}`).join(' · ')}</small></span><span class="row-actions"><strong>${money(group.estimatedCost)}</strong>${group.supplier&&canPage('documents')?`<button type="button" class="btn compact primary" data-purchase-order="${groupIndex}">${t('createPurchaseOrder')}</button>`:''}</span></div>`).join('')}`:`<p class="muted">✓ ${t('noPriority')}</p>`)}${opportunities.length?card(t('supplierSavings'),opportunities.slice(0,6).map(x=>`<div class="row"><span><strong>${esc(x.product)}</strong><br><small class="muted">${esc(x.currentSupplier)} ${money(x.currentPrice)} → ${esc(x.bestSupplier)} ${money(x.bestPrice)} · ${x.offers} ${t('comparedSuppliers')}</small></span><span class="row-actions"><span class="pill good">-${x.savingPct.toFixed(1)}%</span>${x.potentialSaving>0?`<strong>${t('potentialSaving')}: ${money(x.potentialSaving)}</strong>`:''}</span></div>`).join('')):''}${recipeImpacts.length?card(t('recipeSupplierImpact'),recipeImpacts.slice(0,6).map(x=>`<div class="row"><span><strong>${esc(x.recipe)}</strong><br><small class="muted">${x.affectedIngredients} ${t('affectedIngredients')} · ${esc(x.suppliers.join(', '))}</small></span><span class="row-actions"><span class="pill warning">${x.maxChangePct}%</span><strong>${t('foodCost')} ${x.foodCostPercent}%</strong></span></div>`).join('')):''}${card(t('invoicePhoto'),`<div class="form"><input id="invoicePhotoInput" type="file" accept="image/*" capture="environment"><button type="button" id="invoicePhotoAnalyze" class="btn primary">${t('analyzeInvoicePhoto')}</button></div><p class="muted">${t('invoicePhotoHint')}</p>`)}${invoiceDraft?card(t('invoicePhotoReview'),`<form id="invoiceReviewForm" class="form"><input name="supplier" required value="${esc(invoiceDraft.supplier||'')}" placeholder="${t('supplierName')}"><input name="reference" required value="${esc(invoiceDraft.invoiceNumber||'')}" placeholder="${t('invoiceReference')}"><input name="date" required type="date" value="${esc(invoiceDraft.date||today())}"><p class="muted">${t('detectedTotal')}: ${esc(invoiceDraft.total||0)} ${esc(invoiceDraft.currency||state.preferences?.currency||'CHF')}</p><div class="invoice-items">${draftItems.map((x,i)=>`<div class="invoice-item"><label class="invoice-use"><input type="checkbox" name="item_use_${i}" checked> ${t('useLine')}</label><input name="item_name_${i}" required value="${esc(x.name||'')}" placeholder="${t('product')}"><input name="item_qty_${i}" type="number" min="0.001" step="0.001" value="${esc(+x.quantity||0)}" placeholder="${t('quantity')}"><input name="item_unit_${i}" value="${esc(x.unit||'')}" placeholder="${t('unit')}"><input name="item_price_${i}" type="number" min="0" step="0.0001" value="${esc(+x.unitPrice||0)}" placeholder="${t('purchasePrice')}"><small class="muted">${t('confidence')}: ${esc(Math.round((+x.confidence||0)*100))}%</small></div>`).join('')}</div><div class="actions"><button class="btn primary">${t('integrateInvoice')}</button><button type="button" id="invoiceReviewCancel" class="btn">${t('cancel')}</button></div></form>`):''}${card(t('newPurchase'),`<form id="purchaseForm" class="form"><select name="supplier" required><option value="">${t('supplierName')}</option>${state.suppliers.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select><input name="date" required type="date" value="${today()}"><input name="amount" required type="number" min="0" step=".01" placeholder="${t('amount')}"><input name="note" placeholder="${t('note')}"><button class="btn primary">${t('add')}</button></form>${rows(state.purchases,(x,i)=>editingRow('purchases',i)?`<form class="form inline-edit" data-edit-form="purchases" data-index="${i}"><select name="supplier" required><option value="">${t('supplierName')}</option>${state.suppliers.map(k=>`<option value="${esc(k.name)}" ${k.name===x.supplier?'selected':''}>${esc(k.name)}</option>`).join('')}</select><input name="date" type="date" required value="${esc(x.date)}"><input name="amount" type="number" min="0" step=".01" required value="${esc(x.amount)}"><input name="note" value="${esc(x.note)}">${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.supplier)}</strong><br><small class="muted">${esc(x.date)} · ${esc(x.note)}</small></span><span class="row-actions"><strong>${money(x.amount)}</strong>${actions('purchases',i)}</span></div>`,'noPurchases')}`)}</section>`}
function products(){return `<section class="artisan-page module-screen">${head(t('products'))}${moduleSectionNav([['catalog',t('products')],['categories',t('categories')],['recipes',t('recipes')]])}<div data-module-pane="catalog">${card(t('products'),`<form id="productForm" class="form"><input name="name" required placeholder="${t('product')}"><select name="category"><option value="">${t('categories')}</option>${state.categories.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select><input name="cost" type="number" min="0" step=".01" placeholder="${t('purchasePrice')}"><input name="price" type="number" min="0" step=".01" placeholder="${t('sellingPrice')}"><button class="btn primary">${t('add')}</button></form>${rows(state.products,(x,i)=>editingRow('products',i)?`<form class="form inline-edit" data-edit-form="products" data-index="${i}"><input name="name" required value="${esc(x.name)}"><select name="category"><option value="">${t('categories')}</option>${state.categories.map(k=>`<option value="${esc(k.name)}" ${k.name===x.category?'selected':''}>${esc(k.name)}</option>`).join('')}</select><input name="cost" type="number" min="0" step=".01" value="${esc(x.cost)}"><input name="price" type="number" min="0" step=".01" value="${esc(x.price)}">${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.category)}</small></span><span class="row-actions"><strong>${money(x.price)}</strong>${actions('products',i)}</span></div>` ,'noProducts')}`)}</div><div data-module-pane="categories">${card(t('categories'),`<button class="btn primary" data-page="categories">${t('categories')}</button>`)}</div><div data-module-pane="recipes">${card(t('recipes'),`<button class="btn primary" data-page="recipes">${t('recipes')}</button>`)}</div></section>`}
function categories(){return `<section>${head(t('categories'))}${card(t('categories'),`<form id="categoryForm" class="form"><input name="name" required placeholder="${t('categoryName')}"><button class="btn primary">${t('add')}</button></form>${rows(state.categories,(x,i)=>editingRow('categories',i)?`<form class="form inline-edit" data-edit-form="categories" data-index="${i}"><input name="name" required value="${esc(x.name)}">${editButtons()}</form>`:`<div class="row"><strong>${esc(x.name)}</strong>${actions('categories',i)}</div>`,'noCategories')}`)}</section>`}
function invoices(){const payables=invoicePayables(state);return `<section>${head(t('invoices'))}<div class="grid">${card(t('outstanding'),`<div class="kpi">${money(payables.total)}</div>`)}${card(t('dueSoon'),`<div class="kpi">${money(payables.dueSoonAmount)}</div><small class="muted">${payables.dueSoonCount} · ${t('next7Days')}</small>`)}${card(t('overdueInvoices'),`<div class="kpi">${money(payables.overdueAmount)}</div><small class="muted">${payables.overdueCount}</small>`)}</div>${card(t('newInvoice'),`<form id="invoiceForm" class="form"><select name="supplier" required><option value="">${t('supplierName')}</option>${state.suppliers.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select><input name="reference" required placeholder="${t('invoiceReference')}"><label class="document-field"><span>${t('invoiceDate')}</span><input name="date" type="date" value="${today()}" required></label><label class="document-field"><span>${t('dueDate')}</span><input name="dueDate" type="date" required></label><input name="amount" type="number" min="0" step=".01" required placeholder="${t('amount')}"><select name="status"><option value="pending">${t('pending')}</option><option value="paid">${t('paid')}</option></select><button class="btn primary">${t('add')}</button></form><p class="muted">${t('invoiceDueHint')}</p>${rows(state.invoices,(x,i)=>editingRow('invoices',i)?`<form class="form inline-edit" data-edit-form="invoices" data-index="${i}"><select name="supplier" required><option value="">${t('supplierName')}</option>${state.suppliers.map(k=>`<option value="${esc(k.name)}" ${k.name===x.supplier?'selected':''}>${esc(k.name)}</option>`).join('')}</select><input name="reference" required value="${esc(x.reference)}"><input name="date" type="date" required value="${esc(x.date)}"><input name="dueDate" type="date" required value="${esc(x.dueDate||x.date)}"><input name="amount" type="number" min="0" step=".01" required value="${esc(x.amount)}"><select name="status"><option value="pending" ${x.status==='pending'?'selected':''}>${t('pending')}</option><option value="paid" ${x.status==='paid'?'selected':''}>${t('paid')}</option></select>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.supplier)} · ${esc(x.reference)}</strong><br><small class="muted">${t('invoiceDate')} ${esc(x.date)} · ${t('dueDate')} ${esc(x.dueDate||x.date)} · ${t(x.status||'pending')}</small></span><span class="row-actions"><strong>${money(x.amount)}</strong>${x.status!=='paid'&&(x.dueDate||x.date)&&String(x.dueDate||x.date)<today()?`<span class="pill status-urgent">${t('overdue')}</span>`:''}${x.status!=='paid'?`<button type="button" class="btn compact primary" data-invoice-paid="${i}">${t('markPaid')}</button>`:''}${actions('invoices',i)}</span></div>`,'noInvoices')}`)}</section>`}
function recalls(){return `<section>${head(t('recalls'))}${card(t('recalls'),`<form id="recallForm" class="form"><input name="product" required placeholder="${t('product')}"><input name="lot" required placeholder="${t('lot')}"><input name="date" type="date" value="${today()}" required><select name="status"><option value="isolated">${t('isolated')}</option><option value="returned">${t('returned')}</option><option value="destroyed">${t('destroyed')}</option></select><textarea name="action" rows="3" placeholder="${t('actionTaken')}"></textarea><button class="btn primary">${t('add')}</button></form>${rows(state.recalls,(x,i)=>editingRow('recalls',i)?`<form class="form inline-edit" data-edit-form="recalls" data-index="${i}"><input name="product" required value="${esc(x.product)}"><input name="lot" required value="${esc(x.lot)}"><input name="date" type="date" required value="${esc(x.date)}"><select name="status"><option value="isolated" ${x.status==='isolated'?'selected':''}>${t('isolated')}</option><option value="returned" ${x.status==='returned'?'selected':''}>${t('returned')}</option><option value="destroyed" ${x.status==='destroyed'?'selected':''}>${t('destroyed')}</option></select><textarea name="action" rows="3">${esc(x.action)}</textarea>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.product)} · ${t('lot')} ${esc(x.lot)}</strong><br><small class="muted">${esc(x.date)}</small><br><small>${esc(x.action)}</small></span><span class="row-actions"><span class="pill">${t(x.status||'isolated')}</span>${actions('recalls',i)}</span></div>`,'noRecalls')}`)}</section>`}
function allergens(){const coverage=allergenCoverage(state),issues=[...coverage.missing.map(x=>({...x,type:'missing'})),...coverage.mismatched.map(x=>({...x,type:'mismatch'}))];return `<section>${head(t('allergens'))}${coverage.recipes?`<div class="actions page-actions"><span class="pill ${coverage.issues?'warning':'good'}">${t('allergenCoverage')}: ${coverage.covered}/${coverage.recipes}</span></div>`:''}${issues.length?card(t('allergenCoverageAlert'),issues.map(x=>`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${t(x.type==='missing'?'allergenMatrixMissing':'allergenMismatch')}${x.type==='mismatch'?` · ${t('recipe')}: ${esc(x.recipeAllergens||t('none'))} · ${t('allergenMatrix')}: ${esc(x.matrixAllergens||t('none'))}`:''}</small></span><span class="row-actions">${x.type==='missing'?(`<button type="button" class="btn compact" data-allergen-prefill="${x.recipeIndex}">${t('prepareAllergenEntry')}</button>`):(`<button type="button" class="btn compact" data-allergen-sync="${x.recipeIndex}" data-matrix-index="${x.matrixIndex}">${t('syncFromRecipe')}</button>`)}</span></div>`).join('')):''}${card(t('allergens'),`<form id="allergenForm" class="form"><input name="dish" required placeholder="${t('dish')}"><input name="allergens" required placeholder="${t('allergenList')}"><textarea name="note" rows="3" placeholder="${t('note')}"></textarea><button class="btn primary">${t('add')}</button></form>${rows(state.allergens,(x,i)=>editingRow('allergens',i)?`<form class="form inline-edit" data-edit-form="allergens" data-index="${i}"><input name="dish" required value="${esc(x.dish)}"><input name="allergens" required value="${esc(x.allergens)}"><textarea name="note" rows="3">${esc(x.note)}</textarea>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.dish)}</strong><br><small>${esc(x.allergens)}</small><br><small class="muted">${esc(x.note)}</small></span><span class="row-actions">${actions('allergens',i)}</span></div>`,'noAllergens')}`)}</section>`}
function deliveries(){const attention=rejectedDeliveryAttention(state),drafts=rejectedDeliveryTaskDrafts(state),stockOptions=selected=>`<option value="">${t('product')}</option>${state.stock.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}`;return `<section>${head(t('deliveries'))}${attention.count?`<div class="actions page-actions">${drafts.length?`<button type="button" id="generateDeliveryTasks" class="btn primary">${t('createDeliveryTasks')} (${drafts.length})</button>`:''}<span class="pill warning">${t('rejectedDeliveryAlert')}: ${attention.count}</span></div>`:''}${card(t('deliveries'),`<form id="deliveryForm" class="form"><input id="deliverySupplier" name="supplier" required placeholder="${t('supplier')}"><select id="deliveryStock" name="stockId" required>${stockOptions('')}</select><input name="qty" type="number" min="0.01" step=".01" required placeholder="${t('quantity')}"><input name="date" type="date" value="${today()}" required><input name="temperature" type="number" step=".1" placeholder="${t('temperature')} °C"><input name="lot" placeholder="${t('lot')}"><select name="status"><option value="accepted">${t('accepted')}</option><option value="rejected">${t('rejected')}</option></select><button class="btn primary">${t('add')}</button></form>${rows(state.deliveries,(x,i)=>editingRow('deliveries',i)?`<form class="form inline-edit" data-edit-form="deliveries" data-index="${i}"><input name="supplier" required value="${esc(x.supplier)}"><select name="stockId" required>${stockOptions(x.stockId)}</select><input name="qty" type="number" min="0.01" step=".01" required value="${esc(x.qty||'')}"><input name="date" type="date" required value="${esc(x.date)}"><input name="temperature" type="number" step=".1" value="${esc(x.temperature)}"><input name="lot" value="${esc(x.lot)}"><select name="status"><option value="accepted" ${x.status==='accepted'?'selected':''}>${t('accepted')}</option><option value="rejected" ${x.status==='rejected'?'selected':''}>${t('rejected')}</option></select>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(state.stock.find(item=>item.id===x.stockId)?.name||x.product)}</strong><br><small>${esc(x.supplier)} · ${esc(x.lot)} · ${esc(x.qty||0)} ${t('quantity')}</small><br><small class="muted">${esc(x.date)} · ${esc(x.temperature)}°C</small></span><span class="row-actions"><span class="pill">${t(x.status||'accepted')}</span>${actions('deliveries',i)}</span></div>`,'noDeliveries')}`)}</section>`}
