function checklists(){return `<section>${head(t('checklists'))}<p class="muted">${t('routinesFeedHint')}</p>${card(t('checklists'),`<form id="checklistForm" class="form"><select name="type"><option value="opening">${t('opening')}</option><option value="closing">${t('closing')}</option><option value="cleaning">${t('cleaning')}</option></select><input name="title" required placeholder="${t('checklistItem')}"><button class="btn primary">${t('add')}</button></form>${rows(state.checklists,(x,i)=>editingRow('checklists',i)?`<form class="form inline-edit" data-edit-form="checklists" data-index="${i}"><input name="type" value="${esc(x.type)}"><input name="title" required value="${esc(x.title)}">${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.title)}</strong><br><small class="muted">${t(x.type||'opening')}</small></span>${actions('checklists',i)}</div>`,'noChecklists')}`)}</section>`}
