let posCatalogAutoSyncTimer=null;
function schedulePosCatalogAutoSync(reason='catalog-change'){
  if(posCatalogAutoSyncTimer)clearTimeout(posCatalogAutoSyncTimer);
  if(!cloudSession()||!cloudManager()||!cloudRestaurantId())return;
  posCatalogAutoSyncTimer=setTimeout(async()=>{
    posCatalogAutoSyncTimer=null;
    try{
      const result=await publishPosCatalog(cloudRestaurantId(),state,{replace:true});
      posAdminState={...posAdminState,catalog:result.catalog||posAdminState.catalog||[],error:''};
      recordDiagnostic('pos.catalog_auto_synced',{reason,count:Number(result.count)||0});
      if(page==='posAdmin')render();
    }catch(error){
      recordDiagnostic('pos.catalog_auto_sync_error',{reason,message:error?.message||String(error)});
      if(page==='posAdmin'){posAdminState={...posAdminState,error:'Synchronisation POS à reprendre : '+(error?.message||String(error))};render()}
    }
  },350);
}
async function posAdminPublish(){
  const rid=cloudRestaurantId();if(!rid)return;
  try{
    const r=await publishPosCatalog(rid,state,{replace:true});
    posAdminState={...posAdminState,catalog:r.catalog||[],error:''};render();
  }catch(error){posAdminState={...posAdminState,error:error?.message||String(error)};render()}
}

