function focusPosAdminSection(){
  if(page!=='posAdmin'||!posAdminFocus)return;
  const focus=posAdminFocus;
  requestAnimationFrame(()=>{
    let target=null;
    if(focus==='history'){target=document.querySelector('.pos-layout-history');if(target)target.open=true}
    else target=document.querySelector('[data-pos-section="'+focus+'"]');
    if(!target)return;
    posAdminFocus='';
    target.scrollIntoView?.({behavior:'smooth',block:'start'});
    target.classList?.add('pos-focus-highlight');
    setTimeout(()=>target.classList.remove('pos-focus-highlight'),1400);
  });
}
function hubSidebar(){
  const item=(p,k,label)=>canPage(p)?`<button data-page="${p}" data-reset-module-section="1" class="${page===p?'active':''}">${icon(k)}<span>${t(label)}</span></button>`:'';
  const group=(label,content)=>content?`<div class="hub-sidebar-group"><small>${label}</small>${content}</div>`:'';
  return `<aside class="hub-sidebar"><div class="hub-sidebar-brand"><span>ReMaPro</span><b>Hub</b><small>Restaurant Management</small></div><div class="hub-sidebar-scroll">${
    group(t('home'),item('dashboard','dashboard','home'))+
    group(t('operations'),item('operations','operations','operations')+item('orders','orders','orders')+item('reservations','reservations','reservations'))+
    group(t('stock'),item('stock','stock','stock')+item('purchases','purchases','purchases'))+
    group(t('haccp'),item('haccp','haccp','haccp')+item('audits','audits','audits'))+
    group(t('financeNav'),item('finance','finance','financeNav')+item('invoices','invoices','invoices'))+
    group(t('team'),item('team','team','team')+item('planning','planning','planning')+item('documents','documents','documents'))+
    group(t('settings'),item('posAdmin','posAdmin','posAdmin')+item('integrations','settings','integrations')+item('settings','settings','settings'))
  }</div></aside>`;
}
