function patchFor(collection,d){if(collection==='goals')return{metric:d.get('metric'),target:+d.get('target')||0,period:d.get('period')};if(collection==='products')return{name:d.get('name'),category:d.get('category'),cost:+d.get('cost'),price:+d.get('price')};if(collection==='categories')return{name:d.get('name')};if(collection==='orders')return{reference:d.get('reference'),amount:+d.get('amount'),status:d.get('status')};if(collection==='loyalty')return{name:d.get('name'),points:+d.get('points')};if(collection==='customers')return{name:d.get('name'),phone:d.get('phone'),email:d.get('email'),note:d.get('note')};if(collection==='suppliers')return{name:d.get('name'),contact:d.get('contact'),paymentDays:+d.get('paymentDays'),leadTimeDays:+d.get('leadTimeDays')};if(collection==='team')return{name:d.get('name'),role:d.get('role'),hourlyRate:+d.get('hourlyRate')||0};if(collection==='temps')return{equipment:d.get('equipment'),value:d.get('value')};if(collection==='stock')return{name:d.get('name'),unit:d.get('unit'),qty:+d.get('qty'),price:+d.get('price')||0,min:+d.get('min')||0,reorderTarget:+d.get('reorderTarget')||0,preferredSupplier:d.get('preferredSupplier'),barcode:d.get('barcode'),safetyDays:+d.get('safetyDays')||0};if(collection==='shifts')return{employee:d.get('employee'),date:d.get('date'),start:d.get('start'),end:d.get('end')};if(collection==='recipes')return{name:d.get('name'),cost:+d.get('cost'),price:+d.get('price')};if(collection==='reservations')return{name:d.get('name'),time:d.get('time'),covers:+d.get('covers'),status:d.get('status')};if(collection==='incidents')return{title:d.get('title'),note:d.get('note')};if(collection==='waste')return{stockId:d.get('stockId'),product:state.stock.find(x=>x.id===d.get('stockId'))?.name||'',qty:+d.get('qty')};if(collection==='invoices')return{supplier:d.get('supplier'),reference:d.get('reference'),date:d.get('date'),dueDate:d.get('dueDate'),amount:+d.get('amount'),status:d.get('status')};if(collection==='purchases')return{supplier:d.get('supplier'),date:d.get('date'),amount:+d.get('amount'),note:d.get('note')};if(collection==='recalls')return{product:d.get('product'),lot:d.get('lot'),date:d.get('date'),status:d.get('status'),action:d.get('action')};if(collection==='allergens')return{dish:d.get('dish'),allergens:d.get('allergens'),note:d.get('note')};if(collection==='deliveries')return{supplier:d.get('supplier'),stockId:d.get('stockId'),product:state.stock.find(x=>x.id===d.get('stockId'))?.name||'',qty:+d.get('qty')||0,date:d.get('date'),temperature:d.get('temperature'),lot:d.get('lot'),status:d.get('status')};if(collection==='cleaning')return{area:d.get('area'),task:d.get('task'),frequency:d.get('frequency'),responsible:d.get('responsible')};if(collection==='audits')return{date:d.get('date'),type:d.get('type'),score:+d.get('score')||0,actions:d.get('actions')};if(collection==='equipment')return{name:d.get('name'),location:d.get('location'),serviceDate:d.get('serviceDate'),status:d.get('status')};if(collection==='leave')return{employee:d.get('employee'),start:d.get('start'),end:d.get('end'),status:d.get('status'),note:d.get('note')};if(collection==='training')return{employee:d.get('employee'),topic:d.get('topic'),date:d.get('date'),validUntil:d.get('validUntil'),status:d.get('status')};if(collection==='alerts')return{level:d.get('level'),title:d.get('title'),note:d.get('note')};if(collection==='checklists')return{type:d.get('type'),title:d.get('title')};if(collection==='briefings')return{date:d.get('date'),title:d.get('title'),note:d.get('note')};if(collection==='maintenance')return{equipment:d.get('equipment'),note:d.get('note')};if(collection==='handover')return{title:d.get('title'),note:d.get('note')};return{}}
function downloadTextFile(filename,text,type='text/csv;charset=utf-8'){
  const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);
}
async function exportAccountingKind(kind,from,to){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to){alert(t('invalidDateRange'));return}
  try{
    let posData={};
    if(kind!=='purchases'){
      const rid=cloudRestaurantId();if(!rid||!cloudSession()||!cloudManager()){alert(t('cloudManagerRequired'));return}
      posData=await loadPosAccountingExport(rid,{from,to});
    }
    const csv=accountingCsv(kind,{pos:posData,state,from,to});
    downloadTextFile(`remapro-${kind}-${from}-${to}.csv`,csv);
  }catch(error){alert((error?.message||String(error))+' · '+t('accountingExportFailed'))}
}
