document.querySelectorAll('[data-purchase-order]').forEach(b=>b.addEventListener('click',()=>{
  const group=buildPurchasePlan(state).groups[+b.dataset.purchaseOrder];
  if(!group?.supplier||!group.items?.length)return;
  if(!confirm(t('createPurchaseOrderConfirm')))return;
  const lines=group.items.map(x=>`${x.name} — ${x.quantity} ${x.unit} — ${money(x.estimatedCost)}`);
  const ok=saveDocument(state,{type:'purchaseOrder',date:today(),title:`${t('purchaseOrder')} — ${group.supplier}`,details:`${t('estimatedReorderBudget')}: ${money(group.estimatedCost)}\n${lines.join('\n')}`,fields:{supplierName:group.supplier,product:group.items.map(x=>x.name).join(', '),quantity:group.items.map(x=>`${x.quantity} ${x.unit}`).join(', ')},legal:null});
  if(!ok)return;
  persist();editing={collection:'documentPreview',index:0};page='documents';globalThis.history?.pushState?.({remaproPage:'documents',remaproDocument:true},'');render()
}));

